repo_files.metrics.py:
"""Resource telemetry metrics tracker."""

class MemoryTracker:
    def __init__(self):
        self.active_handles: set[str] = set()

    def register(self, handle_id: str) -> None:
        self.active_handles.add(handle_id)

    def unregister(self, handle_id: str) -> None:
        self.active_handles.discard(handle_id)

    @property
    def live_count(self) -> int:
        return len(self.active_handles)

repo_files.cache.py:
"""Bounded cache store with entry expiration and cleanup hooks."""

from collections import OrderedDict
from typing import Any, Callable, Dict, Optional


class BoundedCache:
    def __init__(self, capacity: int = 5):
        self.capacity = capacity
        self._store: OrderedDict[str, Any] = OrderedDict()
        self._listeners: list[Callable[[str, Any], None]] = []

    def add_eviction_listener(self, fn: Callable[[str, Any], None]) -> None:
        self._listeners.append(fn)

    def put(self, key: str, value: Any) -> Optional[tuple[str, Any]]:
        evicted = None
        if key in self._store:
            self._store.move_to_end(key)
            self._store[key] = value
            return None

        if len(self._store) >= self.capacity:
            # Evict oldest entry
            old_key, old_val = self._store.popitem(last=False)
            evicted = (old_key, old_val)
            # BUG: Eviction listener is called, but exceptions or errors are unhandled
            # and listener references are never notified during explicit remove/clear!
            for listener in self._listeners:
                listener(old_key, old_val)

        self._store[key] = value
        return evicted

    def remove(self, key: str) -> Optional[Any]:
        # BUG: remove() pops the item from _store but fails to invoke eviction listeners,
        # leaving external resources/handles dangling and leaked in tracker!
        return self._store.pop(key, None)

    def clear(self) -> None:
        # BUG: clear() simply resets dictionary without firing teardown hooks on existing items
        self._store.clear()

repo_files.session_pool.py:
"""Session manager that acquires and releases tracked resources."""

from typing import Any, Dict, Optional
from cache import BoundedCache
from metrics import MemoryTracker


class SessionPool:
    def __init__(self, capacity: int = 3):
        self.tracker = MemoryTracker()
        self.cache = BoundedCache(capacity=capacity)
        self.cache.add_eviction_listener(self._on_evict)

    def _on_evict(self, key: str, value: Any) -> None:
        self.tracker.unregister(key)

    def acquire_session(self, session_id: str, session_data: Dict[str, Any]) -> None:
        self.tracker.register(session_id)
        self.cache.put(session_id, session_data)

    def terminate_session(self, session_id: str) -> bool:
        val = self.cache.remove(session_id)
        return val is not None

    def close_all(self) -> None:
        self.cache.clear()

reference_fix.cache.py:
"""Bounded cache store with entry expiration and cleanup hooks."""

from collections import OrderedDict
from typing import Any, Callable, Dict, Optional


class BoundedCache:
    def __init__(self, capacity: int = 5):
        self.capacity = capacity
        self._store: OrderedDict[str, Any] = OrderedDict()
        self._listeners: list[Callable[[str, Any], None]] = []

    def add_eviction_listener(self, fn: Callable[[str, Any], None]) -> None:
        self._listeners.append(fn)

    def _notify_listeners(self, key: str, value: Any) -> None:
        for listener in self._listeners:
            listener(key, value)

    def put(self, key: str, value: Any) -> Optional[tuple[str, Any]]:
        evicted = None
        if key in self._store:
            self._store.move_to_end(key)
            self._store[key] = value
            return None

        if len(self._store) >= self.capacity:
            old_key, old_val = self._store.popitem(last=False)
            evicted = (old_key, old_val)
            self._notify_listeners(old_key, old_val)

        self._store[key] = value
        return evicted

    def remove(self, key: str) -> Optional[Any]:
        if key in self._store:
            val = self._store.pop(key)
            self._notify_listeners(key, val)
            return val
        return None

    def clear(self) -> None:
        items = list(self._store.items())
        self._store.clear()
        for k, v in items:
            self._notify_listeners(k, v)
